head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldfil52700";
scwin.form = null;
scwin.loadTp = null;
scwin.returnVal = null;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.loadTp = String((((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (typeof scwin.loadTp !== "undefined" && scwin.loadTp !== null ? scwin.loadTp : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "loadTp" + " (as-is EL 부재 = 빈값이라 진행합니다)"), "")))(dma_pageContext.get("loadTp"))) == null ? '' : (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (typeof scwin.loadTp !== "undefined" && scwin.loadTp !== null ? scwin.loadTp : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "loadTp" + " (as-is EL 부재 = 빈값이라 진행합니다)"), "")))(dma_pageContext.get("loadTp")))).indexOf('$' + '{') >= 0 ? '' : String((((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (typeof scwin.loadTp !== "undefined" && scwin.loadTp !== null ? scwin.loadTp : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "loadTp" + " (as-is EL 부재 = 빈값이라 진행합니다)"), "")))(dma_pageContext.get("loadTp"))) == null ? '' : (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (typeof scwin.loadTp !== "undefined" && scwin.loadTp !== null ? scwin.loadTp : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "loadTp" + " (as-is EL 부재 = 빈값이라 진행합니다)"), "")))(dma_pageContext.get("loadTp"))));
        scwin.returnVal = String((((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (typeof scwin.returnVal !== "undefined" && scwin.returnVal !== null ? scwin.returnVal : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "returnVal" + " (as-is EL 부재 = 빈값이라 진행합니다)"), "")))(dma_pageContext.get("returnVal"))) == null ? '' : (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (typeof scwin.returnVal !== "undefined" && scwin.returnVal !== null ? scwin.returnVal : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "returnVal" + " (as-is EL 부재 = 빈값이라 진행합니다)"), "")))(dma_pageContext.get("returnVal")))).indexOf('$' + '{') >= 0 ? '' : String((((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (typeof scwin.returnVal !== "undefined" && scwin.returnVal !== null ? scwin.returnVal : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "returnVal" + " (as-is EL 부재 = 빈값이라 진행합니다)"), "")))(dma_pageContext.get("returnVal"))) == null ? '' : (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (typeof scwin.returnVal !== "undefined" && scwin.returnVal !== null ? scwin.returnVal : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "returnVal" + " (as-is EL 부재 = 빈값이라 진행합니다)"), "")))(dma_pageContext.get("returnVal"))));
        await scwin.init_rowCopy();
        await scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldfil52700.onpageload' });
    }
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "__rb0", fn: function () { return "전체 " + String(dma_page.get("total")) + "건 [" + String(dma_page.get("currentPage")) + "/" + String(dma_page.get("pageCount")) + " Page] "; } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { /* TODO Stage2: [sdd] 행 복사 대상 부재:  it.childId */ continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_pageBody = async function () {
    try {
        scwin.form = (document.searchForm || { elements: [] });
        if (scwin.returnVal === "N") {
            await $c.win.alert('처리 중 오류가 발생하였습니다. 시스템 관리자에게 문의하여 주세요.');
        } else {
            if (scwin.loadTp === "5") {
                await $c.win.alert('제출 처리되었습니다.');
            } else {
                if (scwin.loadTp === "6") {
                    await $c.win.alert('수정요청 처리되었습니다.');
                }
            }
        }

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil52700.onpageload' }); }
};

// [A] 초기 목록 미해결 — jldfil52700: 열자마자 목록을 채울 근거가 없다(진입 URL 0 · 자기 목록 tx 0 · 화면 자신의 액션 URL 도 못 가름)

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name slc_pageSize_onchange
 * @description slc_pageSize 변경 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.slc_pageSize_onchange = function(e){
    try {
        scwin.initPageIndex()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil52700.slc_pageSize_onchange' }); }
};

/**
 * @method
 * @name grd_pageList_oncellclick
 * @description grd_pageList 셀 클릭 이벤트
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_pageList_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_pageList');
        if (!dl) { /* TODO Stage2: [sdd] 행 동작 대상 목록 없음: dlt_pageList */ return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; }
        if (columnId === "__rowAct") { if (r["listProcsStatCd"] === '33' || r["listProcsStatCd"] === '36') { await scwin.adjReqPop(r["follwBzProcsNo"]); return; } if (r["listProcsStatCd"] === '30' || r["listProcsStatCd"] === '35' || r["listProcsStatCd"] === '37') { await scwin.editStatus(r["follwBzProcsNo"]); return; } return; } if (r["listProcsStatCd"] === '') { await scwin.viewDetail(r["bzProcsNo"], "1"); return; }
        if (r["listProcsStatCd"] === '30') { await scwin.viewDetail(r["bzProcsNo"], "2"); return; }
        if (r["listProcsStatCd"] === '35') { await scwin.viewDetail(r["bzProcsNo"], "2"); return; }
        if (r["listProcsStatCd"] === '37') { await scwin.viewDetail(r["bzProcsNo"], "2"); return; }
        await scwin.viewDetail(r["bzProcsNo"]); return;
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_pageList.oncellclick' });
    }
};

/**
 * @method
 * @name krxpage_pagenavigator_75_onclick
 * @description krxpage_pagenavigator_75 클릭 이벤트
 * @param {Number} index index
 * @returns {void}
 * @hidden N
 */
scwin.krxpage_pagenavigator_75_onclick = function (index) {
    try {
    const pi = (index && typeof index === 'object') ? index.newSelectedIndex : index; scwin.search();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "jldfil52700.krxpage_pagenavigator_75_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_viewDetail
 * @description view Detail 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_viewDetail = async function () {
    const sbmOptions = {
        id: "tx_viewDetail",
        method: "post",
        action: "",
        target: "dlt_pageList=body",
        isProcessMsg: false
    };
    return await $c.sbm.executeDynamic(sbmOptions);
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name initPageIndex
 * @description init Page Index 처리
 * @returns {void}
 * @hidden N
 */
scwin.initPageIndex = function () {
    $c.util.getComponent("ipt_pageIndex").setValue(1);
    scwin.search();
};

/**
 * @method
 * @name grd_pageList_fmt_column2
 * @description grd page List fmt column2 처리
 * @param {*} data 데이터
 * @param {*} formattedData 포맷된 값
 * @param {*} r r
 * @param {*} c c
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_pageList_fmt_column2 = async function (data, formattedData, r, c) {
    try {
        const dl = $c.util.getComponent("dlt_pageList");
        const v = String(dl && dl.getCellData ? (dl.getCellData(r, "stkcertListDd") ?? '') : '');
        if (v !== '') { return (console.error('[sdd] 미실현 라벨 갈래: column2 (expression)'), String(data ?? '')); }
        return '';
    } catch (e) { await $c.exception.handleError(e, { notify: 'none', context: "grd_pageList.column2" }); return String(data ?? ''); }
};

/**
 * @method
 * @name grd_pageList_fmt_listProcsStatNm
 * @description grd page List fmt list Procs Stat Nm 처리
 * @param {*} data 데이터
 * @param {*} formattedData 포맷된 값
 * @param {*} r r
 * @param {*} c c
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_pageList_fmt_listProcsStatNm = async function (data, formattedData, r, c) {
    try {
        const dl = $c.util.getComponent("dlt_pageList");
        const v = String(dl && dl.getCellData ? (dl.getCellData(r, "listProcsStatCd") ?? '') : '');
        if (v === '') { return '<a href="javascript:void(0)"' + (false ? ' class="lnk"' : '') + '>' + String((dl && dl.getCellData ? dl.getCellData(r, "listProcsStatNm") : '') ?? '') + '</a>'; }
        if (v === '30') { return '<a href="javascript:void(0)"' + (false ? ' class="lnk"' : '') + '>' + "작성중" + '</a>'; }
        if (v === '35') { return '<a href="javascript:void(0)"' + (false ? ' class="lnk"' : '') + '>' + "수정가능" + '</a>'; }
        if (v === '37') { return '<a href="javascript:void(0)"' + (false ? ' class="lnk"' : '') + '>' + "재작성" + '</a>'; }
        return String((dl && dl.getCellData ? dl.getCellData(r, "listProcsStatNm") : '') ?? '');
    } catch (e) { await $c.exception.handleError(e, { notify: 'none', context: "grd_pageList.listProcsStatNm" }); return String(data ?? ''); }
};

/**
 * @method
 * @name grd_pageList_fmt_column7
 * @description grd page List fmt column7 처리
 * @param {*} data 데이터
 * @param {*} formattedData 포맷된 값
 * @param {*} r r
 * @param {*} c c
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_pageList_fmt_column7 = async function (data, formattedData, r, c) {
    try {
        const dl = $c.util.getComponent("dlt_pageList");
        const v = String(dl && dl.getCellData ? (dl.getCellData(r, "listProcsStatCd") ?? '') : '');
        if (['33','36'].indexOf(v) >= 0) { return '<a href="javascript:void(0)"' + (false ? ' class="lnk"' : '') + '>' + "수정요청" + '</a>'; }
        return '';
    } catch (e) { await $c.exception.handleError(e, { notify: 'none', context: "grd_pageList.column7" }); return String(data ?? ''); }
};

/**
 * @method
 * @name grd_pageList_fillAct
 * @description grd page List fill Act 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_pageList_fillAct = async function () {
    try {
        const dl = $c.util.getComponent('dlt_pageList');
        if (!dl || !dl.getTotalRow) { return; }
        for (let i = 0; i < dl.getRowCount(); i++) {
            const r = dl.getRowJSON(i);
            let v = '-';
            if (r) { if (r["listProcsStatCd"] === '33' || r["listProcsStatCd"] === '36') { v = "수정요청"; } else if (r["listProcsStatCd"] === '30' || r["listProcsStatCd"] === '35' || r["listProcsStatCd"] === '37') { v = "제출"; } }
            dl.setCellData(i, "__rowAct", v);
        }
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_pageList.fillAct' });
    }
};

/**
 * @method
 * @name search
 * @description search 처리
 * @returns {void}
 * @hidden N
 */
scwin.search = function () {
    $c.util.getComponent("ipt_method").setValue("searchPipelineProgList");
    scwin.form.submit();
};

/**
 * @method
 * @name viewDetail
 * @description view Detail 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.viewDetail = async function () {
    $c.util.getComponent("ipt_method").setValue("loadPipelineProgDetail");
    $c.util.getComponent("ipt_bzProcsNo").setValue(bzProcsNo);
    await scwin.tx_viewDetail();
};

/**
 * @method
 * @name editStatus
 * @description edit Status 처리
 * @param {*} bzProcsNo bzProcsNo
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.editStatus = async function (bzProcsNo) {
    $c.util.getComponent("ipt_method").setValue("submitPipelineProg");
    $c.util.getComponent("ipt_bzProcsNo").setValue(bzProcsNo);
    if (await $c.win.confirm('제출하시겠습니까?')) {
        scwin.form.submit();
    }
};

/**
 * @method
 * @name adjReqPop
 * @description adj Req Pop 처리
 * @param {*} bzProcsNo bzProcsNo
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.adjReqPop = async function (bzProcsNo) {
    w = '500';
    h = '250';
    l = screen.width / 2 - w / 2;
    t = screen.height / 2 - h / 2;
    const corpSearchURL = '/jldfil52710/jldfil52710.xml';
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — "
    await $c.win.openPopup((function (__u) { const __s = String(__u == null ? "" : __u); if (!/\.xml(\?|#|$)/.test(__s)) { throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + __s, unresolved: "nav:" + __s }; } return __u; })(corpSearchURL), { id: "AdjReqPop", scrollbars: false, resizable: false, width: "500", height: "250", type: "pageFramePopup" }, { method: "selectPipelineAdjReq", bzProcsNo: bzProcsNo });
};
